PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_version VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS settings(org_id TEXT PRIMARY KEY,max_media_count INTEGER NOT NULL DEFAULT 2 CHECK(max_media_count>0),version INTEGER NOT NULL DEFAULT 1,dispatch_enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires_at REAL NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS partners(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,contract_end TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,source_partner_id TEXT NOT NULL REFERENCES partners(id),enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS catalog(series_id TEXT PRIMARY KEY,brand_id TEXT NOT NULL,brand_name TEXT NOT NULL,series_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS routes(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,buyer_id TEXT NOT NULL REFERENCES partners(id),receiver_id TEXT NOT NULL REFERENCES partners(id),media_id TEXT NOT NULL REFERENCES partners(id),enabled INTEGER NOT NULL DEFAULT 1,adapter_version TEXT NOT NULL DEFAULT 'mock-v1',mode TEXT NOT NULL DEFAULT 'ACK',supports_query INTEGER NOT NULL DEFAULT 1,supports_idempotency INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,lead_no TEXT NOT NULL,phone_cipher TEXT NOT NULL,phone_hmac TEXT NOT NULL,name_cipher TEXT NOT NULL,series_id TEXT NOT NULL,city_code TEXT NOT NULL,channel_id TEXT NOT NULL REFERENCES channels(id),collected_at TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',max_sales_override INTEGER CHECK(max_sales_override IS NULL OR max_sales_override>0),exclusive_media_id TEXT,exclusive_until TEXT,cost_fen INTEGER,created_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(org_id,lead_no));
CREATE INDEX IF NOT EXISTS lead_phone ON leads(org_id,phone_hmac,series_id,collected_at);
CREATE INDEX IF NOT EXISTS lead_status ON leads(org_id,status,collected_at);
CREATE TABLE IF NOT EXISTS ingestions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,channel_id TEXT NOT NULL REFERENCES channels(id),source_record_id TEXT NOT NULL,lead_id TEXT REFERENCES leads(id),status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',payload_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(org_id,channel_id,source_record_id));
CREATE TABLE IF NOT EXISTS consents(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,lead_id TEXT NOT NULL REFERENCES leads(id),recipient_id TEXT NOT NULL REFERENCES partners(id),evidence_ref TEXT NOT NULL,notice_version TEXT NOT NULL,granted_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,review_status TEXT NOT NULL,reviewed_by TEXT,UNIQUE(lead_id,recipient_id));
CREATE TABLE IF NOT EXISTS demands(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,demand_no TEXT NOT NULL,agency_demand_no TEXT,buyer_id TEXT NOT NULL REFERENCES partners(id),receiver_id TEXT NOT NULL REFERENCES partners(id),media_id TEXT NOT NULL REFERENCES partners(id),route_id TEXT NOT NULL REFERENCES routes(id),series_id TEXT NOT NULL REFERENCES catalog(series_id),city_codes TEXT NOT NULL,target_total INTEGER NOT NULL CHECK(target_total>0),daily_limit INTEGER NOT NULL CHECK(daily_limit>0),priority INTEGER NOT NULL DEFAULT 50,start_at TEXT NOT NULL,end_at TEXT NOT NULL,max_age_hours INTEGER NOT NULL DEFAULT 168,dedup_days INTEGER NOT NULL DEFAULT 30,unit_price_fen INTEGER NOT NULL DEFAULT 0 CHECK(unit_price_fen>=0),pricing_basis TEXT NOT NULL DEFAULT 'VALID',status TEXT NOT NULL DEFAULT 'DRAFT',created_by TEXT NOT NULL,approved_by TEXT,version INTEGER NOT NULL DEFAULT 1,reserved_count INTEGER NOT NULL DEFAULT 0 CHECK(reserved_count>=0),valid_count INTEGER NOT NULL DEFAULT 0 CHECK(valid_count>=0),created_at TEXT NOT NULL,UNIQUE(org_id,media_id,demand_no));
CREATE TABLE IF NOT EXISTS demand_versions(id TEXT PRIMARY KEY,demand_id TEXT NOT NULL REFERENCES demands(id),revision INTEGER NOT NULL,snapshot TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(demand_id,revision));
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,lead_id TEXT NOT NULL REFERENCES leads(id),demand_id TEXT NOT NULL REFERENCES demands(id),receiver_id TEXT NOT NULL REFERENCES partners(id),media_id TEXT NOT NULL REFERENCES partners(id),route_id TEXT NOT NULL REFERENCES routes(id),route_snapshot TEXT NOT NULL,demand_snapshot TEXT NOT NULL,payload_cipher TEXT NOT NULL,price_fen INTEGER NOT NULL,pricing_basis TEXT NOT NULL,send_status TEXT NOT NULL DEFAULT 'QUEUED',storage_status TEXT NOT NULL DEFAULT 'PENDING',validity_status TEXT NOT NULL DEFAULT 'PENDING',callback_status TEXT NOT NULL DEFAULT 'NONE',settlement_status TEXT NOT NULL DEFAULT 'UNCONFIRMED',evidence_level TEXT NOT NULL DEFAULT 'NONE',first_sent_at TEXT,acked_at TEXT,stored_at TEXT,validated_at TEXT,callback_last_at TEXT,storage_version INTEGER NOT NULL DEFAULT 0,validity_version INTEGER NOT NULL DEFAULT 0,quota_state TEXT NOT NULL DEFAULT 'RESERVED',day TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS delivery_lead ON deliveries(org_id,lead_id,media_id);
CREATE INDEX IF NOT EXISTS delivery_demand ON deliveries(org_id,demand_id,created_at);
CREATE TABLE IF NOT EXISTS hops(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES deliveries(id),hop_no INTEGER NOT NULL,from_id TEXT NOT NULL,to_id TEXT NOT NULL,acceptance TEXT NOT NULL DEFAULT 'PENDING',external_id TEXT,media_record_id TEXT,accepted_at TEXT,UNIQUE(delivery_id,hop_no));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES deliveries(id),attempt_no INTEGER NOT NULL,idempotency_key TEXT NOT NULL,outcome TEXT NOT NULL,http_status INTEGER,created_at TEXT NOT NULL,UNIQUE(delivery_id,attempt_no));
CREATE TABLE IF NOT EXISTS dedup_registry(org_id TEXT NOT NULL,phone_hmac TEXT NOT NULL,series_id TEXT NOT NULL,media_id TEXT NOT NULL,owner_delivery_id TEXT NOT NULL REFERENCES deliveries(id),blocked_until TEXT NOT NULL,PRIMARY KEY(org_id,phone_hmac,series_id,media_id));
CREATE TABLE IF NOT EXISTS daily_counter(demand_id TEXT NOT NULL REFERENCES demands(id),day TEXT NOT NULL,reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0),sent INTEGER NOT NULL DEFAULT 0 CHECK(sent>=0),PRIMARY KEY(demand_id,day));
CREATE TABLE IF NOT EXISTS quota_ledger(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES deliveries(id),demand_id TEXT NOT NULL REFERENCES demands(id),event_key TEXT NOT NULL UNIQUE,reserved_delta INTEGER NOT NULL,valid_delta INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL UNIQUE REFERENCES deliveries(id),status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS callback_events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,partner_id TEXT NOT NULL,event_id TEXT NOT NULL,delivery_id TEXT REFERENCES deliveries(id),external_id TEXT,event_type TEXT NOT NULL,event_version INTEGER,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,body TEXT NOT NULL,payload_hash TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',UNIQUE(org_id,partner_id,event_id));
CREATE TABLE IF NOT EXISTS inbox(id TEXT PRIMARY KEY,event_ref TEXT NOT NULL UNIQUE REFERENCES callback_events(id),status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS idempotency(org_id TEXT NOT NULL,actor_id TEXT NOT NULL,path TEXT NOT NULL,key TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(org_id,actor_id,path,key));
CREATE TABLE IF NOT EXISTS nonces(key_id TEXT NOT NULL,nonce TEXT NOT NULL,expires_at REAL NOT NULL,PRIMARY KEY(key_id,nonce));
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,channel_id TEXT NOT NULL REFERENCES channels(id),filename TEXT NOT NULL,rows_cipher TEXT NOT NULL,preview TEXT NOT NULL,status TEXT NOT NULL,created_by TEXT NOT NULL,result TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_requests(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,lead_id TEXT NOT NULL REFERENCES leads(id),type TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_notices(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES privacy_requests(id),recipient_id TEXT NOT NULL REFERENCES partners(id),status TEXT NOT NULL DEFAULT 'PENDING',confirmed_at TEXT,UNIQUE(request_id,recipient_id));
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT,'audit immutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_log BEGIN SELECT RAISE(ABORT,'audit immutable'); END;
CREATE TABLE IF NOT EXISTS exports(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,created_by TEXT NOT NULL,purpose TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,token_hash TEXT,expires_at REAL,used INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS risk_blocklist(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,phone_hmac TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(org_id,phone_hmac));
